    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }
}

contracts/tunecamp/TuneCampCheckout.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./TuneCampNFT.sol";

/**
 * @title TuneCampCheckout
 * @notice Handles purchases of TuneCamp NFTs with ETH or USDC.
 * @dev Upgraded to support EIP-1167 Minimal Proxy via TuneCampFactory.
 */
contract TuneCampCheckout is Initializable, OwnableUpgradeable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ─── Constants ───────────────────────────────────────────────────────────
    uint256 public constant PLATFORM_FEE_BPS = 1500;   // 15.00%
    uint256 public constant BPS_DENOMINATOR  = 10_000;

    // ─── State ───────────────────────────────────────────────────────────────
    TuneCampNFT public nft;
    IERC20      public usdc;
    address public treasury;

    /// @dev Artists on the Pro plan bypass the 15% split
    mapping(address => bool) public isProArtist;

    /// @dev trackId → role → price in USDC (6 decimals)
    mapping(uint256 => mapping(TuneCampNFT.TokenRole => uint256)) public priceUSDC;

    /// @dev trackId → role → price in ETH (wei)
    mapping(uint256 => mapping(TuneCampNFT.TokenRole => uint256)) public priceETH;

    // ─── Events ──────────────────────────────────────────────────────────────
    event Purchase(
        address indexed buyer,
        uint256 indexed trackId,
        TuneCampNFT.TokenRole role,
        address indexed paymentToken,   // address(0) = ETH
        uint256 totalPaid,
        uint256 artistShare,
        uint256 platformShare,
        uint256 quantity
    );

    event ProStatusUpdated(address indexed artist, bool isPro);
    event PriceUpdated(
        uint256 indexed trackId,
        TuneCampNFT.TokenRole role,
        uint256 newPriceUSDC,
        uint256 newPriceETH
    );
    event TreasuryUpdated(address indexed newTreasury);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ─── Initialization ──────────────────────────────────────────────────────
    function initialize(
        address admin,
        address _nft,
        address _usdc,
        address _treasury
    ) public initializer {
        __Ownable_init(admin);

        require(_nft       != address(0), "Invalid NFT address");
        require(_usdc      != address(0), "Invalid USDC address");
        require(_treasury  != address(0), "Invalid treasury address");

        nft      = TuneCampNFT(_nft);
        usdc     = IERC20(_usdc);
        treasury = _treasury;
    }

    // ─── Purchase: USDC ──────────────────────────────────────────────────────
    function purchaseWithUSDC(
        uint256 trackId,
        TuneCampNFT.TokenRole role,
        uint256 quantity
    ) external nonReentrant {
        require(quantity > 0, "Quantity must be > 0");

        uint256 unitPrice = priceUSDC[trackId][role];
        require(unitPrice > 0, "USDC price not set");

        uint256 total = unitPrice * quantity;
        address artist = _getArtist(trackId);

        // Pull payment from buyer
        usdc.safeTransferFrom(msg.sender, address(this), total);

        // Split and distribute
        (uint256 artistShare, uint256 platformShare) = _computeSplit(total, artist);
        usdc.safeTransfer(artist, artistShare);
        if (platformShare > 0) {
            usdc.safeTransfer(treasury, platformShare);
        }

        // Mint NFT
        nft.mint(msg.sender, trackId, role, quantity);

        emit Purchase(
            msg.sender, trackId, role,
            address(usdc), total,
            artistShare, platformShare, quantity
        );
    }

    // ─── Purchase: ETH ───────────────────────────────────────────────────────
    function purchaseWithETH(
        uint256 trackId,
        TuneCampNFT.TokenRole role,
        uint256 quantity
    ) external payable nonReentrant {
        require(quantity > 0, "Quantity must be > 0");

        uint256 unitPrice = priceETH[trackId][role];
        require(unitPrice > 0, "ETH price not set");

        uint256 total = unitPrice * quantity;
        require(msg.value == total, "Incorrect ETH amount sent");

        address artist = _getArtist(trackId);

        // Split and distribute
        (uint256 artistShare, uint256 platformShare) = _computeSplit(total, artist);

        (bool sentArtist, ) = artist.call{value: artistShare}("");
        require(sentArtist, "ETH transfer to artist failed");

        if (platformShare > 0) {
            (bool sentTreasury, ) = treasury.call{value: platformShare}("");
            require(sentTreasury, "ETH transfer to treasury failed");
        }

        // Mint NFT
        nft.mint(msg.sender, trackId, role, quantity);

        emit Purchase(
            msg.sender, trackId, role,
            address(0), total,
            artistShare, platformShare, quantity
        );
    }

    // ─── Admin: prices ───────────────────────────────────────────────────────
    function setPrice(
        uint256 trackId,
        TuneCampNFT.TokenRole role,
        uint256 _priceUSDC,
        uint256 _priceETH
    ) external onlyOwner {
        priceUSDC[trackId][role] = _priceUSDC;
        priceETH[trackId][role]  = _priceETH;
        emit PriceUpdated(trackId, role, _priceUSDC, _priceETH);
    }

    function setPriceBatch(
        uint256[]                    calldata trackIds,
        TuneCampNFT.TokenRole[]      calldata roles,
        uint256[]                    calldata pricesUSDC,
        uint256[]                    calldata pricesETH
    ) external onlyOwner {
        uint256 len = trackIds.length;
        require(
            len == roles.length &&
            len == pricesUSDC.length &&
            len == pricesETH.length,
            "Array length mismatch"
        );
        for (uint256 i = 0; i < len; i++) {
            priceUSDC[trackIds[i]][roles[i]] = pricesUSDC[i];
            priceETH[trackIds[i]][roles[i]]  = pricesETH[i];
            emit PriceUpdated(trackIds[i], roles[i], pricesUSDC[i], pricesETH[i]);
        }
    }

    // ─── Admin: plan management ───────────────────────────────────────────────
    function setProArtist(address artist, bool status) external onlyOwner {
        isProArtist[artist] = status;
        emit ProStatusUpdated(artist, status);
    }

    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Invalid treasury");
        treasury = _treasury;
        emit TreasuryUpdated(_treasury);
    }

    // ─── View helpers ─────────────────────────────────────────────────────────
    function previewSplit(uint256 total, address artist)
        external view
        returns (uint256 artistShare, uint256 platformShare)
    {
        return _computeSplit(total, artist);
    }

    // ─── Internal ────────────────────────────────────────────────────────────
    function _getArtist(uint256 trackId) internal view returns (address artist) {
        artist = nft.trackArtist(trackId);
        require(artist != address(0), "Track not registered");
    }

    function _computeSplit(uint256 total, address artist)
        internal view
        returns (uint256 artistShare, uint256 platformShare)
    {
        if (isProArtist[artist]) {
            // Pro plan: artist keeps 100%
            artistShare   = total;
            platformShare = 0;
        } else {
            // Free plan: 85% artist, 15% platform
            platformShare = (total * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
            artistShare   = total - platformShare;
        }
    }

    // ─── Safety ──────────────────────────────────────────────────────────────
    function rescueERC20(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(owner(), amount);
    }

    receive() external payable {}
}

contracts/tunecamp/TuneCampFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// ─── Deployed on Base Network (chainId: 8453) ────────────────────────────────
// USDC on Base: 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913
//
// Usage flow for a self-hosters:
//   1. Call deployInstance(instanceName, baseMetadataURI, treasury)
//   2. Factory creates Minimal Proxies (Clones) for NFT + Checkout
//   3. Factory initializes both proxies
//   4. Grants MINTER_ROLE on NFT to Checkout proxy
//   5. Emits InstanceDeployed with all addresses → frontend reads this

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";
import "./TuneCampNFT.sol";
import "./TuneCampCheckout.sol";

contract TuneCampFactory is Ownable {

    // ─── Constants & Immutables ──────────────────────────────────────────────
    address public usdcAddress;

    /// @dev The master logic contracts (implementation)
    address public immutable nftImplementation;
    address public immutable checkoutImplementation;

    // ─── Registry ────────────────────────────────────────────────────────────
    struct Instance {
        address admin;
        address nft;
        address checkout;
        string  name;
        uint256 deployedAt;
    }

    /// @dev All deployed instances, in order.
    Instance[] public instances;

    /// @dev admin wallet → list of instance indexes they own.
    mapping(address => uint256[]) private _instancesByAdmin;

    /// @dev NFT address → instance index (for reverse lookup).
    mapping(address => uint256) public instanceIndexByNFT;

    // ─── Events ──────────────────────────────────────────────────────────────
    event InstanceDeployed(
        uint256 indexed instanceId,
        address indexed admin,
        address nft,
        address checkout,
        string  name
    );

    // ─── Constructor ─────────────────────────────────────────────────────────
    /**
     * @param _usdc           USDC Token address on the target network.
     * @param _nftLogic       Address of the pre-deployed TuneCampNFT master logic.
     * @param _checkoutLogic  Address of the pre-deployed TuneCampCheckout master logic.
     */
    constructor(
        address _usdc,
        address _nftLogic,
        address _checkoutLogic
    ) Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC address");
        require(_nftLogic != address(0), "Invalid NFT logic address");
        require(_checkoutLogic != address(0), "Invalid Checkout logic address");

        usdcAddress = _usdc;
        nftImplementation = _nftLogic;
        checkoutImplementation = _checkoutLogic;
    }

    // ─── Core: deploy an instance ─────────────────────────────────────────────
    /**
     * @notice Deploy a fresh TuneCampNFT + TuneCampCheckout for a self-hosted instance using Minimal Proxies.
     *
     * @param instanceName    Human-readable label (e.g. "MyMusicNode").
     * @param baseMetadataURI Base URI for NFT metadata (e.g. "https://mynode.xyz/meta/").
     * @param treasury        Address that collects the 15% platform fee.
     *
     * @return nftAddress      Deployed TuneCampNFT proxy address.
     * @return checkoutAddress Deployed TuneCampCheckout proxy address.
     */
    function deployInstance(
        string  calldata instanceName,
        string  calldata baseMetadataURI,
        address          treasury
    )
        external
        returns (address nftAddress, address checkoutAddress)
    {
        require(bytes(instanceName).length    > 0, "Name required");
        require(bytes(baseMetadataURI).length > 0, "Base URI required");
        require(treasury != address(0),            "Invalid treasury");

        // ── 1. Clone & Initialize NFT ─────────────────────────────────────────
        nftAddress = Clones.clone(nftImplementation);
        TuneCampNFT nftContract = TuneCampNFT(nftAddress);

        // Factory acts as temporary admin during initialization
        nftContract.initialize(address(this), baseMetadataURI);

        // ── 2. Clone & Initialize Checkout ────────────────────────────────────
        checkoutAddress = Clones.clone(checkoutImplementation);
        TuneCampCheckout checkoutContract = TuneCampCheckout(payable(checkoutAddress));

        // Pass the new NFT proxy and treasury to the checkout proxy
        checkoutContract.initialize(msg.sender, nftAddress, usdcAddress, treasury);

        // ── 3. Grant MINTER_ROLE on NFT to Checkout ──────────────────────────
        nftContract.grantRole(nftContract.MINTER_ROLE(), checkoutAddress);

        // ── 4. Transfer full NFT control to the calling admin ────────────────
        nftContract.grantRole(nftContract.DEFAULT_ADMIN_ROLE(), msg.sender);
        nftContract.revokeRole(nftContract.DEFAULT_ADMIN_ROLE(), address(this));

        // Note: Checkout ownership is already set to msg.sender during initialize

        // ── 5. Register in the on-chain registry ─────────────────────────────
        uint256 instanceId = instances.length;

        instances.push(Instance({
            admin:      msg.sender,
            nft:        nftAddress,
            checkout:   checkoutAddress,
            name:       instanceName,
            deployedAt: block.timestamp
        }));

        _instancesByAdmin[msg.sender].push(instanceId);
        instanceIndexByNFT[nftAddress] = instanceId;

        emit InstanceDeployed(instanceId, msg.sender, nftAddress, checkoutAddress, instanceName);
    }

    // ─── Views ────────────────────────────────────────────────────────────────

    function instanceCount() external view returns (uint256) {
        return instances.length;
    }

    function instancesOf(address admin) external view returns (uint256[] memory) {
        return _instancesByAdmin[admin];
    }

    function getInstance(uint256 instanceId)
        external view
        returns (Instance memory)
    {
        require(instanceId < instances.length, "Instance does not exist");
        return instances[instanceId];
    }

    function getInstanceByNFT(address nft)
        external view
        returns (Instance memory)
    {
        uint256 idx = instanceIndexByNFT[nft];
        require(instances[idx].nft == nft, "NFT not registered");
        return instances[idx];
    }

    // ─── Admin: update USDC address (e.g. for testnets) ──────────────────────
    function setUSDC(address _usdc) external onlyOwner {
        require(_usdc != address(0), "Invalid USDC");
        usdcAddress = _usdc;
    }
}

contracts/tunecamp/TuneCampNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC1155/ERC1155Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TuneCampNFT
 * @notice ERC-1155 multi-role NFT for Tunecamp music tracks.
 * @dev Upgraded to support EIP-1167 Minimal Proxy via TuneCampFactory.
 */
contract TuneCampNFT is Initializable, ERC1155Upgradeable, AccessControlUpgradeable {
    using Strings for uint256;

    // ─── Roles ───────────────────────────────────────────────────────────────
    bytes32 public constant MINTER_ROLE  = keccak256("MINTER_ROLE");
    bytes32 public constant ARTIST_ROLE  = keccak256("ARTIST_ROLE");

    // ─── Enums ───────────────────────────────────────────────────────────────
    enum TokenRole { LICENSE, OWNERSHIP, COLLECTIBLE }

    // ─── Storage ─────────────────────────────────────────────────────────────
    /// @dev trackId → artist address
    mapping(uint256 => address) public trackArtist;

    /// @dev trackId → role → max mintable supply (0 = unlimited)
    mapping(uint256 => mapping(TokenRole => uint256)) public maxSupply;

    /// @dev trackId → role → units minted so far
    mapping(uint256 => mapping(TokenRole => uint256)) public mintedSupply;

    /// @dev tokenId → custom URI (overrides base if set)
    mapping(uint256 => string) private _tokenURIs;

    string private _baseMetadataURI;

    // ─── Events ──────────────────────────────────────────────────────────────
    event TrackRegistered(uint256 indexed trackId, address indexed artist);
    event TrackMinted(
        address indexed to,
        uint256 indexed trackId,
        TokenRole role,
        uint256 tokenId,
        uint256 amount
    );

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ─── Initialization ──────────────────────────────────────────────────────
    function initialize(
        address admin,
        string memory baseMetadataURI_
    ) public initializer {
        __ERC1155_init(baseMetadataURI_);
        __AccessControl_init();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _baseMetadataURI = baseMetadataURI_;
    }

    // ─── Admin: register a track ─────────────────────────────────────────────
    function registerTrack(
        uint256 trackId,
        address artist,
        uint256 maxLicense,
        uint256 maxOwnership,
        uint256 maxCollectible
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(trackArtist[trackId] == address(0), "Track already registered");
        require(artist != address(0), "Invalid artist address");

        trackArtist[trackId] = artist;
        maxSupply[trackId][TokenRole.LICENSE]      = maxLicense;
        maxSupply[trackId][TokenRole.OWNERSHIP]    = maxOwnership;
        maxSupply[trackId][TokenRole.COLLECTIBLE]  = maxCollectible;

        emit TrackRegistered(trackId, artist);
    }

    // ─── Minting (called by TuneCampCheckout) ────────────────────────────────
    function mint(
        address to,
        uint256 trackId,
        TokenRole role,
        uint256 amount
    ) external onlyRole(MINTER_ROLE) {
        require(trackArtist[trackId] != address(0), "Track not registered");

        uint256 max = maxSupply[trackId][role];
        if (max > 0) {
            require(
                mintedSupply[trackId][role] + amount <= max,
                "Exceeds max supply for this role"
            );
        }

        mintedSupply[trackId][role] += amount;
        uint256 tokenId = encodeTokenId(trackId, role);
        _mint(to, tokenId, amount, "");

        emit TrackMinted(to, trackId, role, tokenId, amount);
    }

    // ─── URI ─────────────────────────────────────────────────────────────────
    function uri(uint256 tokenId) public view override returns (string memory) {
        if (bytes(_tokenURIs[tokenId]).length > 0) {
            return _tokenURIs[tokenId];
        }
        return string(abi.encodePacked(_baseMetadataURI, tokenId.toString(), ".json"));
    }

    function setTokenURI(uint256 tokenId, string calldata newURI)
        external onlyRole(DEFAULT_ADMIN_ROLE)
    {
        _tokenURIs[tokenId] = newURI;
    }

    function setBaseURI(string calldata newBaseURI)
        external onlyRole(DEFAULT_ADMIN_ROLE)
    {
        _baseMetadataURI = newBaseURI;
    }

    // ─── Helpers ─────────────────────────────────────────────────────────────
    function encodeTokenId(uint256 trackId, TokenRole role)
        public pure returns (uint256)
    {
        return trackId * 10 + uint256(role);
    }

    function decodeTokenId(uint256 tokenId)
        public pure returns (uint256 trackId, TokenRole role)
    {
        trackId = tokenId / 10;
        role    = TokenRole(tokenId % 10);
    }

    // ─── Interface support ───────────────────────────────────────────────────
    function supportsInterface(bytes4 interfaceId)
        public view override(ERC1155Upgradeable, AccessControlUpgradeable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

